def risk_level(likelihood, impact):
    score = likelihood * impact
    if score >= 15 or impact == 5:
        return 'high'
    if score >= 6:
        return 'medium'
    return 'low'

def coverage_report(risks, tested):
    report = {lvl: {'total': 0, 'tested': 0, 'untested': []} for lvl in ('high', 'medium', 'low')}
    for name, l, i in risks:
        entry = report[risk_level(l, i)]
        entry['total'] += 1
        if name in tested:
            entry['tested'] += 1
        else:
            entry['untested'].append(name)
    for entry in report.values():
        entry['untested'].sort()
    return report
